            'cooldown_steps': 0,
            'rendezvous_count': 0,
            'tracking_mode': False,
            'last_step': 0,
            'phase': 0,  # 0: not in phase, 1: phase-1, 2: phase-2
            'rendezvous_phase_count': 0,
