            else:
                gx = x_max - 0.02
            gy = ty
        else:
            # Check for obstacles
            obstacles = sandbox.get_terrain_obstacles()
            for obs in obstacles:
                ox = obs.position.x
                oy = obs.position.y
                dx = sx - ox
                dy = sy - oy
                dist = math.hypot(dx, dy)
