                    gy = oy + 0.1
                    break
            else:
                # No obstacle collision, proceed to track
                dx = tx - sx
                dy = ty - sy
                distance = math.hypot(dx, dy)
                if distance > 8.5:
                    # Predict target position based on velocity
                    predicted_tx = tx + state['tvx'] * dt
                    predicted_ty = ty + state['tvy'] * dt
                    desired_angle = math.atan2(predicted_ty - sy, predicted_tx - sx)
                    thrust = 120.0 if not state['cooldown_active'] else 40.0
                    budget = sandbox.get_remaining_impulse_budget()
                    if budget > 0:
                        fx = thrust * math.cos(desired_angle)
