    if not hasattr(agent_body, '_state'):
        agent_body._state = {
            'last_tx': 0.0, 'last_ty': 0.0,
            'tvx': 0.0, 'tvy': 0.0,
            'activation_counter': 0,
            'cooldown_active': False,
            'cooldown_steps': 0,
            'rendezvous_count': 0,
            'tracking_mode': False,
            'last_step': 0,
            'phase': 0,
            'rendezvous_phase_count': 0,
            'last_target_x': 0.0, 'last_target_y': 0.0,
            'gx': 0.0, 'gy': 0.0,
            'gx_prev': 0.0, 'gy_prev': 0.0
        }

    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()
    angle = sandbox.get_seeker_heading()
    x_min, x_max = sandbox.get_corridor_bounds()
    dt = 1.0 / 60.0

    # Ensure seeker stays above ground
    if sy < 1.0:
        state['gy'] = 1.35
        state['gx'] = sx
    else:
        state['gy'] = sy
        state['gx'] = sx

    # Update target velocity estimate using position history
    if step_count % 5 == 0 and step_count > 5:
        state['tvx'] = 0.8 * (tx - state['last_tx']) / dt + 0.2 * state['tvx']
        state['tvy'] = 0.8 * (ty - state['last_ty']) / dt + 0.2 * state['tvy']
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
